import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 9 A cold welcome","description":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 9 A cold welcome","description":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 一般过去时与事件顺序，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 8 The best and the worst","link":"/life/english/new-concept/book-2/unit-01/lesson-008"},"next":{"text":"第二册：实践与进步 · Lesson 10 Not for jazz","link":"/life/english/new-concept/book-2/unit-01/lesson-010"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 8 The best and the worst","link":"/life/english/new-concept/book-2/unit-01/lesson-008"},"next":{"text":"第二册：实践与进步 · Lesson 10 Not for jazz","link":"/life/english/new-concept/book-2/unit-01/lesson-010"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-009.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-009.md"}'),i={name:"life/english/new-concept/book-2/unit-01/lesson-009.md"};function l(r,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-9-a-cold-welcome" tabindex="-1">第二册：实践与进步 · Lesson 9 A cold welcome <a class="header-anchor" href="#第二册-实践与进步-·-lesson-9-a-cold-welcome" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 9 A cold welcome&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>一群人按约定在钟楼前等候，却发现时钟没有走动；练习用时间介词定位事件。本课的语言观察是：at 配具体钟点，on 配某一天，in 配较大时间范围。叙述约会失败时，先交代约定时间，再给出发现问题的时刻。完成学习后，请叙述一次等候，至少写一个钟点、一个地点及意外情况。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>crowd</td><td>/kraʊd/</td><td>n.</td><td>人群</td><td>a large crowd</td></tr><tr><td>clock</td><td>/klɒk/</td><td>n.</td><td>钟</td><td>a station clock</td></tr><tr><td>welcome</td><td>/ˈwelkəm/</td><td>n.</td><td>欢迎</td><td>a warm welcome</td></tr><tr><td>silent</td><td>/ˈsaɪlənt/</td><td>adj.</td><td>无声的</td><td>remain silent</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>at half past eight — 在八点半</li><li>wait in silence — 静静等候，silence 在这里不可数</li></ul><h2 id="语法讲解-一般过去时与事件顺序" tabindex="-1">语法讲解：一般过去时与事件顺序 <a class="header-anchor" href="#语法讲解-一般过去时与事件顺序" aria-label="Permalink to &quot;语法讲解：一般过去时与事件顺序&quot;">​</a></h2><p>一般过去时把动作放在已经结束的过去时间内，肯定句用动词过去式；疑问和否定借助 did 后，实义动词恢复原形。be 的过去式是 was/were，不再加 did。叙事中连续的过去式通常按出现顺序推进情节；单凭一句过去式不能推断动作持续多久。先确定时间范围，再选择动词形式，不要把汉语中的“了”机械地翻译成完成时。本课应用：at 配具体钟点，on 配某一天，in 配较大时间范围。叙述约会失败时，先交代约定时间，再给出发现问题的时刻。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The crowd reached the square at half past eight.</p></blockquote><p>人群在八点半到达了广场。</p><p>reached 是及物动词，后直接接 the square；at half past eight 是具体钟点，不用 in。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>reach the square 不加 to；arrive at the square 才需要 at。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>练习 half past eight 的连读，在 crowd reached 间保留两个词的辅音边界。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The crowd reached the square at half past eight. The clock above the gate was silent. A worker explained that it needed repairs.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>叙述一次等候，至少写一个钟点、一个地点及意外情况。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：reached 是及物动词，后直接接 the square；at half past eight 是具体钟点，不用 in。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：reach the square 不加 to；arrive at the square 才需要 at。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 at/on/in：We met ___ half past eight.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> at</p><p><strong>解析：</strong> 具体钟点前使用 at。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>为什么时钟没有报时？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> It needed repairs.</p><p><strong>解析：</strong> 示范明确给出维修原因，没有说人群来早了。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>将 We reached the square 改为含 arrived 的同义句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> We arrived at the square.</p><p><strong>解析：</strong> arrive 是不及物动词，到较小地点用 at。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：一般过去时与事件顺序。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-008">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-010">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",l]]);export{u as __pageData,b as default};
